import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Eye, EyeOff, Globe2, Lock, Moon, Phone, ShieldCheck, Sparkles, Sun, Star, Timer } from 'lucide-react';
import { useCourier } from '../lib/store';
import { Logo, cn } from '../components/ui';

export const Login = () => {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { login, authed } = useCourier();
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [show, setShow] = useState(false);
  const [error, setError] = useState('');
  const [dark, setDark] = useState(() => document.documentElement.classList.contains('dark'));

  if (authed) navigate('/', { replace: true });

  const toggleTheme = () => {
    const next = !dark;
    setDark(next);
    document.documentElement.classList.toggle('dark', next);
    localStorage.setItem('maxshop-courier-theme', next ? 'dark' : 'light');
  };

  const cycleLang = () => i18n.changeLanguage(i18n.language === 'uz' ? 'ru' : i18n.language === 'ru' ? 'en' : 'uz');

  const submit = (e) => {
    e.preventDefault();
    if (phone.replace(/\D/g, '').length < 9 || password.length < 4) {
      setError('Telefon yoki parolni to\'g\'ri kiriting');
      return;
    }
    login(phone);
    navigate('/');
  };

  const demo = () => {
    login('+998 90 123 45 67');
    navigate('/');
  };

  return (
    <div className="aurora flex min-h-screen flex-col bg-[var(--bg)]">
      {/* top bar */}
      <header className="flex items-center justify-between px-5 pt-5">
        <Logo />
        <div className="flex items-center gap-2">
          <button onClick={cycleLang} className="glass-bar flex h-10 items-center gap-1.5 rounded-2xl px-2.5 text-[10px] font-extrabold shadow-sm transition hover:border-brand-400/50"><Globe2 size={14} className="text-brand-600 dark:text-brand-400" /> {i18n.language.toUpperCase()}</button>
          <button onClick={toggleTheme} className="icon-btn h-10 transition hover:scale-105">{dark ? <Sun size={15} /> : <Moon size={15} />}</button>
        </div>
      </header>

      {/* hero */}
      <div className="mx-auto w-full max-w-md px-5 pt-8">
        <div className="animate-fade-up">
          <span className="badge border border-brand-500/25 bg-brand-500/10 text-brand-700 dark:text-brand-300"><Sparkles size={11} className="text-brand-500" /> {t('courierPanel')}</span>
          <h1 className="mt-3.5 font-display text-[34px] font-extrabold leading-[1.08] tracking-tight">
            Max<br /><span className="text-gradient">SHOP Courier</span>
          </h1>
          <p className="mt-2.5 max-w-[300px] text-sm font-medium leading-relaxed text-[var(--muted)]">{t('loginSubtitle')}</p>
        </div>
        <div className="stagger mt-5 flex gap-2">
          {[
            { icon: Star, text: t('bonus') },
            { icon: Timer, text: t('onTime') },
            { icon: ShieldCheck, text: t('support') },
          ].map((b) => (
            <div key={b.text} className="glass-bar flex items-center gap-1.5 rounded-2xl px-2.5 py-2 text-[9px] font-extrabold shadow-sm">
              <b.icon size={12} className="text-brand-600 dark:text-brand-400" /> {b.text}
            </div>
          ))}
        </div>
      </div>

      {/* form card */}
      <div className="mx-auto mt-6 w-full flex-1 px-5 pb-10">
        <div className="card animate-fade-up p-5 shadow-soft sm:p-6">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="font-display text-lg font-extrabold tracking-tight">{t('loginTitle')}</h2>
              <p className="mt-1 text-[11px] font-bold text-[var(--muted)]">{t('demoHint')}</p>
            </div>
            <span className="relative">
              <span className="absolute inset-0 rounded-2xl bg-amber-400/30 blur-lg" />
              <span className="relative flex h-12 w-12 items-center justify-center rounded-2xl bg-amber-400/15 text-2xl">🛵</span>
            </span>
          </div>

          <form onSubmit={submit} className="mt-5 space-y-3.5">
            <div>
              <label className="label">{t('phone')}</label>
              <div className="relative">
                <Phone size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
                <input value={phone} onChange={(e) => { setPhone(e.target.value); setError(''); }} className="input pl-10" placeholder="+998 90 123 45 67" />
              </div>
            </div>
            <div>
              <label className="label">{t('password')}</label>
              <div className="relative">
                <Lock size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
                <input type={show ? 'text' : 'password'} value={password} onChange={(e) => { setPassword(e.target.value); setError(''); }} className="input pl-10 pr-11" placeholder="••••" />
                <button type="button" onClick={() => setShow((v) => !v)} className="absolute right-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)] transition hover:text-brand-600">{show ? <EyeOff size={15} /> : <Eye size={15} />}</button>
              </div>
            </div>
            {error && <p className="animate-pop rounded-xl border border-rose-300/40 bg-rose-500/10 px-3 py-2 text-[10px] font-bold text-rose-500">{error}</p>}
            <button type="submit" className="btn-primary w-full">{t('loginBtn')} →</button>
          </form>

          <div className="my-4 flex items-center gap-2 text-[10px] font-extrabold uppercase tracking-wider text-[var(--muted)]"><span className="h-px flex-1 bg-[var(--border)]" /> {t('or', { defaultValue: 'or' })} <span className="h-px flex-1 bg-[var(--border)]" /></div>
          <button onClick={demo} className="btn-secondary w-full text-xs"><Sparkles size={14} className="text-brand-600 dark:text-brand-400" /> {t('demoLogin')}</button>
        </div>

        <p className="mt-5 text-center text-[10px] font-bold text-[var(--muted)]">© 2026 MaxSHOP · {t('courierPanel')}</p>
      </div>
    </div>
  );
};
